// ─────────────────────────────────────────────────────────────────────────
//  01 · revenue report★★☆
//  concepts: groupingBy · summingLong · LinkedHashMap
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.stream.*;

class Exercise {

    record Order(String customer, String status, long totalCents) {}

    /** Paid revenue per customer, highest first (ties by name), at most n entries, in order. */
    static Map<String, Long> topRevenue(List<Order> orders, int n) {
        return orders.stream()
            .filter(o -> o.status().equals("paid"))
            .collect(Collectors.groupingBy(Order::customer, Collectors.summingLong(Order::totalCents)))
            .entrySet().stream()
            .sorted(Map.Entry.<String, Long>comparingByValue(Comparator.reverseOrder()).thenComparing(Map.Entry.comparingByKey()))
            .limit(n)
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue, (a, b) -> a, LinkedHashMap::new));
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("sums paid orders per customer", () -> eq(topRevenue(List.of(new Order("ana", "paid", 500), new Order("bo", "paid", 700), new Order("ana", "paid", 300), new Order("bo", "open", 9999)), 10).toString(), "{ana=800, bo=700}"));
        test("ties are ordered by name", () -> eq(new ArrayList<>(topRevenue(List.of(new Order("cy", "paid", 10), new Order("al", "paid", 10), new Order("bo", "paid", 20)), 3).keySet()), List.of("bo", "al", "cy")));
        test("at most n entries", () -> eq(topRevenue(List.of(new Order("a", "paid", 1), new Order("b", "paid", 2), new Order("c", "paid", 3)), 2).keySet(), new LinkedHashSet<>(List.of("c", "b"))));
        test("no paid orders gives an empty map (boundary)", () -> ok(topRevenue(List.of(new Order("a", "open", 5)), 3).isEmpty(), "expected empty"));
        test("repeat customers never throw Duplicate key", () -> eq(topRevenue(List.of(new Order("a", "paid", 1), new Order("a", "paid", 1), new Order("a", "paid", 1)), 1).get("a"), 3L));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

